            "config.json": "{\n  \"name\": \"Bottom bar\",\n  \"category\": \"data\",\n  \"description\": \"A bar below each scene with the date, the time, the Wi-Fi signal and the battery.\",\n  \"version\": \"1.0.0\",\n  \"fields\": [],\n  \"output\": [\n    {\n      \"name\": \"image\",\n      \"type\": \"image\"\n    }\n  ]\n}\n",
            "app.tsx": "// A bar below the scene it wraps: the date, the time, the Wi-Fi signal and the battery.\nconst pad = (n) => String(n).padStart(2, '0')\nconst on = (value) => value === true || value === 'true'\n\nconst clock = (now, seconds) =>\n  `${pad(now.getHours())}:${pad(now.getMinutes())}${seconds ? `:${pad(now.getSeconds())}` : ''}`\n\n// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.\nfunction Signal({ rssi, color }) {\n  if (typeof rssi !== 'number') return null\n  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1\n  return (\n    <div className=\"flex items-end gap-[0.4vh] h-[3vh]\">\n      {[1.2, 1.8, 2.4, 3].map((height, i) => (\n        <div className={`w-[0.7vh] h-[${height}vh] bg-[${color}] ${i < level ? '' : 'opacity-30'}`} />\n      ))}\n    </div>\n  )\n}\n\nconst Battery = ({ percent }) => (typeof percent === 'number' ? <span>{`${percent}%`}</span> : null)\nconst days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']\nconst months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']\n\nexport function get(app) {\n  const { barColor, textColor, showSeconds } = app.state\n  const now = new Date()\n  return (\n    <div className={`flex flex-col w-full h-full bg-[${barColor}] text-[${textColor}]`}>\n      <yield />\n      <div className=\"flex items-center h-[9vh] px-[3vw] gap-[2vw]\">\n        <span className=\"flex-1 text-[3.6vh] font-semibold truncate\">\n          {`${days[now.getDay()]} ${now.getDate()} ${months[now.getMonth()]}`}\n        </span>\n        <span className=\"text-[5vh] font-bold\">{clock(now, on(showSeconds))}</span>\n        <div className=\"flex-1 flex items-center justify-end gap-[1.5vw] text-[3vh] font-semibold\">\n          <Signal rssi={app.frame.wifiRssi} color={textColor} />\n          <Battery percent={app.frame.batteryPercent} />\n        </div>\n      </div>\n    </div>\n  )\n}\n"
